-- domain: media_plaza
-- Main production Stream seed batch 09. Review project and release prerequisites before running.
-- All 500 rows contain a main private cover and verified signed HLS.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '90s';
CREATE TEMP TABLE plaza_video_release_input (
  source_video_id text NOT NULL,
  source_video_url text NOT NULL,
  source_heat integer NOT NULL,
  model_id text NOT NULL,
  prompt text NOT NULL,
  prompt_zh text NOT NULL,
  source_row integer NOT NULL,
  source_bytes bigint NOT NULL,
  width integer NOT NULL,
  height integer NOT NULL,
  duration_ms integer NOT NULL,
  poster_path text NOT NULL,
  poster_bytes integer NOT NULL,
  poster_width integer NOT NULL,
  poster_height integer NOT NULL,
  stream_uid text NOT NULL,
  stream_host text NOT NULL,
  PRIMARY KEY (source_video_id),
  UNIQUE (stream_uid)
) ON COMMIT DROP;
INSERT INTO pg_temp.plaza_video_release_input (source_video_id, source_video_url, source_heat, model_id, prompt, prompt_zh, source_row, source_bytes, width, height, duration_ms, poster_path, poster_bytes, poster_width, poster_height, stream_uid, stream_host)
SELECT source_video_id, source_video_url, source_heat, model_id, prompt, prompt_zh, source_row, source_bytes, width, height, duration_ms, poster_path, poster_bytes, poster_width, poster_height, stream_uid, stream_host FROM jsonb_to_recordset(convert_from(decode('', 'base64'), 'UTF8')::jsonb)
AS input(source_video_id text, source_video_url text, source_heat integer, model_id text, prompt text, prompt_zh text, source_row integer, source_bytes bigint, width integer, height integer, duration_ms integer, poster_path text, poster_bytes integer, poster_width integer, poster_height integer, stream_uid text, stream_host text);
INSERT INTO pg_temp.plaza_video_release_input (source_video_id, source_video_url, source_heat, model_id, prompt, prompt_zh, source_row, source_bytes, width, height, duration_ms, poster_path, poster_bytes, poster_width, poster_height, stream_uid, stream_host)
SELECT source_video_id, source_video_url, source_heat, model_id, prompt, prompt_zh, source_row, source_bytes, width, height, duration_ms, poster_path, poster_bytes, poster_width, poster_height, stream_uid, stream_host FROM jsonb_to_recordset(convert_from(decode('', 'base64'), 'UTF8')::jsonb)
AS input(source_video_id text, source_video_url text, source_heat integer, model_id text, prompt text, prompt_zh text, source_row integer, source_bytes bigint, width integer, height integer, duration_ms integer, poster_path text, poster_bytes integer, poster_width integer, poster_height integer, stream_uid text, stream_host text);

DO $checks$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_temp.plaza_video_release_input) THEN
    RAISE EXCEPTION 'No verified posters and private Stream assets in this batch';
  END IF;
  IF (SELECT count(DISTINCT stream_host) FROM pg_temp.plaza_video_release_input) <> 1 THEN
    RAISE EXCEPTION 'Use a single configured Stream customer host';
  END IF;
  IF NOT EXISTS (
    SELECT FROM storage.buckets
    WHERE id = 'media-plaza-video' AND NOT public
      AND 'image/jpeg' = ANY (allowed_mime_types)
  ) THEN
    RAISE EXCEPTION 'Private main video cover bucket missing';
  END IF;
  IF EXISTS (
    SELECT FROM pg_temp.plaza_video_release_input AS r
    WHERE NOT EXISTS (
      SELECT FROM storage.objects AS o
      WHERE o.bucket_id = 'media-plaza-video' AND o.name = r.poster_path
        AND o.metadata->>'mimetype' = 'image/jpeg'
        AND o.metadata->>'size' = r.poster_bytes::text
    )
  ) THEN
    RAISE EXCEPTION 'A verified main cover is missing or changed';
  END IF;
END
$checks$;

SELECT pg_advisory_xact_lock(hashtextextended('media_plaza:stream-seed-release', 0));

CREATE TEMP TABLE plaza_video_publish_rows ON COMMIT DROP AS
SELECT r.*,
  model.name AS canonical_model_name,
  'https://' || r.stream_host || '/' || r.stream_uid || '/manifest/video.m3u8' AS stable_playback_url,
  jsonb_build_object(
    'prompt', r.prompt, 'prompt_zh', r.prompt_zh, 'prompt_zh_source', 'translation_pack',
    'model_id', r.model_id, 'input_mode', model.input_mode,
    'duration_s', CASE WHEN r.duration_ms > 7500 THEN 10 ELSE 5 END,
    'resolution', model.resolution, 'aspect_ratio', '16:9', 'audio', true,
    'reference_artifact_id', NULL, 'source_heat', r.source_heat
  ) AS generation_snapshot
FROM pg_temp.plaza_video_release_input AS r
JOIN (VALUES
  ('wan-3-0-pro',         'Wan 3.0 Pro',        't2v', '1080p'),
  ('wan-3-0-reference',   'Wan 3.0 Reference',  'r2v', '720p'),
  ('minimax-h3-max',      'MiniMax H3 Max',     't2v', '1080P'),
  ('minimax-h3-max-r2v',  'MiniMax H3 Max R2V', 'r2v', '1080P'),
  ('seedance-1-5-pro',    'Seedance 1.5 Pro',   't2v', '720p'),
  ('seedance-2-0-r2v',    'Seedance 2.0 R2V',   'r2v', '720p')
) AS model(id, name, input_mode, resolution) ON model.id = r.model_id;

DO $models$
BEGIN
  IF (SELECT count(*) FROM pg_temp.plaza_video_publish_rows)
     <> (SELECT count(*) FROM pg_temp.plaza_video_release_input) THEN
    RAISE EXCEPTION 'Missing reviewed seed model mapping';
  END IF;
END
$models$;

INSERT INTO media_plaza.video_artifacts (
  origin, stream_uid, playback_url, byte_size, width, height, duration_ms,
  poster_path, poster_width, poster_height, source_video_id, source_video_url
)
SELECT 'civitai_seed', stream_uid, stable_playback_url, source_bytes, width, height, duration_ms,
  poster_path, poster_width, poster_height, source_video_id, source_video_url
FROM pg_temp.plaza_video_publish_rows
ORDER BY source_video_id
ON CONFLICT (origin, source_video_id) DO NOTHING;

DO $artifacts$
BEGIN
  IF EXISTS (
    SELECT FROM pg_temp.plaza_video_publish_rows AS r
    JOIN media_plaza.video_artifacts AS a ON a.origin = 'civitai_seed' AND a.source_video_id = r.source_video_id
    WHERE ROW(a.stream_uid, a.playback_url, a.byte_size, a.width, a.height, a.duration_ms,
              a.poster_path, a.poster_width, a.poster_height, a.source_video_url)
      IS DISTINCT FROM
          ROW(r.stream_uid, r.stable_playback_url, r.source_bytes, r.width, r.height, r.duration_ms,
              r.poster_path, r.poster_width, r.poster_height, r.source_video_url)
  ) THEN
    RAISE EXCEPTION 'Seed artifact conflict';
  END IF;
END
$artifacts$;

INSERT INTO media_plaza.image_plaza_works (
  title, description, model_id, model_name, width, height, tags, snapshot, published_at,
  origin, source_heat, media_type, video_artifact_id, duration_ms, source_video_id, source_video_url
)
SELECT left(r.prompt, 80), left(r.prompt, 500), r.model_id, r.canonical_model_name, r.width, r.height,
  '{}', r.generation_snapshot, timestamptz '2026-01-01 00:00:00+00' + r.source_row * interval '1 second',
  'civitai_seed', r.source_heat, 'video', a.id, r.duration_ms, r.source_video_id, r.source_video_url
FROM pg_temp.plaza_video_publish_rows AS r
JOIN media_plaza.video_artifacts AS a ON a.origin = 'civitai_seed' AND a.source_video_id = r.source_video_id
ORDER BY r.source_video_id
ON CONFLICT (source_video_id) WHERE media_type = 'video' AND origin = 'civitai_seed' DO NOTHING;

DO $works$
BEGIN
  IF EXISTS (
    SELECT FROM pg_temp.plaza_video_publish_rows AS r
    JOIN media_plaza.video_artifacts AS a ON a.origin = 'civitai_seed' AND a.source_video_id = r.source_video_id
    LEFT JOIN media_plaza.image_plaza_works AS w
      ON w.media_type = 'video' AND w.origin = 'civitai_seed' AND w.source_video_id = r.source_video_id
    WHERE w.id IS NULL
      OR ROW(w.video_artifact_id, w.snapshot, w.model_id, w.model_name, w.source_video_url, w.source_heat)
         IS DISTINCT FROM
         ROW(a.id, r.generation_snapshot, r.model_id, r.canonical_model_name, r.source_video_url, r.source_heat)
  ) THEN
    RAISE EXCEPTION 'Seed work conflict';
  END IF;
END
$works$;

SELECT count(*) AS matched_works,
       count(*) FILTER (WHERE w.deleted_at IS NULL) AS published_works
FROM pg_temp.plaza_video_publish_rows AS r
JOIN media_plaza.image_plaza_works AS w
  ON w.media_type = 'video' AND w.origin = 'civitai_seed' AND w.source_video_id = r.source_video_id;
COMMIT;
